CREATE TABLE IF NOT EXISTS org_departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, code text NOT NULL UNIQUE, description text, parent_department_id uuid REFERENCES org_departments(id), status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS org_positions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL UNIQUE, department_id uuid REFERENCES org_departments(id), employment_type text NOT NULL DEFAULT 'full_time', level text, reports_to_position_id uuid REFERENCES org_positions(id), purpose text, responsibilities text, required_skills text, qualifications text, location text, budget_status text NOT NULL DEFAULT 'planned', status text NOT NULL DEFAULT 'planned', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workforce_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position_id uuid REFERENCES org_positions(id), full_name text NOT NULL, email text, phone text, stage text NOT NULL DEFAULT 'prospect', source text, notes text, consent_status text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workforce_employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position_id uuid REFERENCES org_positions(id), full_name text NOT NULL, email text, phone text, employee_number text UNIQUE, employment_status text NOT NULL DEFAULT 'planned', start_date date, manager_employee_id uuid REFERENCES workforce_employees(id), onboarding_status text NOT NULL DEFAULT 'not_started', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_org_positions_department ON org_positions(department_id,status);
CREATE INDEX IF NOT EXISTS idx_candidates_position_stage ON workforce_candidates(position_id,stage);
CREATE INDEX IF NOT EXISTS idx_employees_status ON workforce_employees(employment_status,onboarding_status);